document.addEventListener('DOMContentLoaded', () => {
  const telemetry = window.__FRAMER_TELEMETRY__ || {};
  const waapiList = telemetry.waapi || [];
  const scrollMatrix = telemetry.scrollMatrix || {};
  const hoverMap = telemetry.hoverMap || {};
  const clickStates = telemetry.clickStates || [];

  // 1. Replay Time-Triggered & Infinite Loop WAAPI Animations
  const playedInitial = new Set();
  waapiList.forEach(item => {
    const el = document.querySelector(`[data-f-id="${item.id}"]`);
    if (!el || !item.keyframes || !item.keyframes.length) return;
    const opts = {
      ...item.options,
      iterations: item.options.iterations === 'Infinity' ? Infinity : item.options.iterations
    };

    if (item.phase === 'time') {
      if (opts.iterations === Infinity) {
        el.animate(item.keyframes, opts);
      } else if (!playedInitial.has(item.id)) {
        playedInitial.add(item.id);
        const io = new IntersectionObserver((entries) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              el.animate(item.keyframes, opts);
              io.unobserve(el);
            }
          });
        }, { threshold: 0.1 });
        io.observe(el);
      }
    }
  });

  // 2. Replay Scroll-Scrubbed Transforms & Opacity Curves (60fps)
  const scrollIds = Object.keys(scrollMatrix);
  if (scrollIds.length > 0) {
    const syncScroll = () => {
      const sy = window.scrollY;
      for (const id of scrollIds) {
        const el = document.querySelector(`[data-f-id="${id}"]`);
        if (!el) continue;
        const points = scrollMatrix[id];
        if (!points || !points.length) continue;

        let best = points[0];
        let minDiff = Math.abs(sy - best.y);
        for (let i = 1; i < points.length; i++) {
          const d = Math.abs(sy - points[i].y);
          if (d < minDiff) {
            minDiff = d;
            best = points[i];
          }
        }
        if (best.transform) el.style.transform = best.transform;
        if (best.opacity !== undefined) el.style.opacity = best.opacity;
      }
    };
    window.addEventListener('scroll', () => requestAnimationFrame(syncScroll), { passive: true });
    syncScroll();
  }

  // 3. Replay Variant Class Swaps & WAAPI Hover Animations
  Object.keys(hoverMap).forEach(rootId => {
    const root = document.querySelector(`[data-f-id="${rootId}"]`);
    if (!root) return;
    const data = hoverMap[rootId];

    root.addEventListener('pointerenter', () => {
      if (data.hoverClass && data.defaultClass) {
        root.className = data.hoverClass;
      }
      (data.waapi || []).forEach(anim => {
        const target = document.querySelector(`[data-f-id="${anim.id}"]`) || root;
        target.animate(anim.keyframes, { ...anim.options, fill: 'forwards' });
      });
    });

    root.addEventListener('pointerleave', () => {
      if (data.defaultClass) {
        root.className = data.defaultClass;
      }
      (data.waapi || []).forEach(anim => {
        const target = document.querySelector(`[data-f-id="${anim.id}"]`) || root;
        const rev = [...anim.keyframes].reverse();
        target.animate(rev, { ...anim.options, fill: 'forwards' });
      });
    });
  });

  // 4. Replay Click / Toggle Variant States (FAQs, Tabs, Pricing Toggles)
  clickStates.forEach(item => {
    let toggled = false;
    document.addEventListener('click', (e) => {
      const trigger = e.target.closest(`[data-f-id="${item.triggerId}"]`);
      if (!trigger) return;
      const container = document.querySelector(`[data-f-id="${item.containerId}"]`);
      if (!container) return;
      e.preventDefault();
      toggled = !toggled;
      if (document.startViewTransition) {
        document.startViewTransition(() => {
          container.innerHTML = toggled ? item.stateB : item.stateA;
        });
      } else {
        container.innerHTML = toggled ? item.stateB : item.stateA;
      }
    });
  });

  // 5. 3D Perspective Tilt & Magnetic Cards
  document.querySelectorAll('[style*="perspective"], [data-framer-name*="Card"], [data-perspective="true"]').forEach(card => {
    card.addEventListener('mousemove', (e) => {
      const r = card.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - 0.5;
      const y = (e.clientY - r.top) / r.height - 0.5;
      card.style.transform = `perspective(1000px) rotateX(${(-y * 8).toFixed(2)}deg) rotateY(${(x * 8).toFixed(2)}deg) scale3d(1.01, 1.01, 1.01)`;
    });
    card.addEventListener('mouseleave', () => {
      card.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)';
    });
  });

  // 6. Fallback Infinite Marquee Runner
  document.querySelectorAll('[data-framer-marquee]').forEach(track => {
    const speed = parseFloat(track.getAttribute('data-framer-marquee')) || 42;
    let offset = 0;
    const tick = () => {
      offset -= speed / 60;
      const half = track.scrollWidth / 2;
      if (half > 0 && Math.abs(offset) >= half) offset = 0;
      track.style.transform = `translate3d(${offset}px, 0, 0)`;
      requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  });
});
